-- Phase 92: Vendor & Third-Party Management control plane.
-- Procurement, MDM, Contracts, Risk, Reliability, Continuity, Architecture, Finance and Integration Hub remain canonical.
-- quality: allow-nonconcurrent-index reason=new-empty-vendor-management-tables

create type public.vendor_context_type as enum('masterapp_platform_vendors','tenant_vendors');

alter table public.plans add column if not exists vendor_management_enabled boolean not null default false,add column if not exists vendor_due_diligence_enabled boolean not null default false,add column if not exists vendor_renewal_management_enabled boolean not null default false,add column if not exists vendor_exit_planning_enabled boolean not null default false,add column if not exists vendor_sla_management_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists vendor_management_enabled boolean not null default false,add column if not exists vendor_due_diligence_enabled boolean not null default false,add column if not exists vendor_renewal_management_enabled boolean not null default false,add column if not exists vendor_exit_planning_enabled boolean not null default false,add column if not exists vendor_sla_management_enabled boolean not null default false;

create table public.vendor_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permission_key text not null,scope_refs text[] not null default '{}',granted_at timestamptz not null default now(),unique(organization_id,user_id,permission_key));
create table public.vendor_profiles(id uuid primary key default gen_random_uuid(),context_type public.vendor_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,third_party_ref text not null,mdm_entity_ref text,supplier_id uuid references public.suppliers(id) on delete restrict,name text not null,vendor_type text not null check(vendor_type in('supplier','technology_provider','payment_provider','marketplace','logistics_provider','fiscal_provider','AI_provider','communications_provider','consultant','maintenance_provider','hardware_vendor','integration_partner','other')),relationship_status text not null default 'prospect' check(relationship_status in('prospect','under_evaluation','onboarding','active','restricted','suspended','renewal_review','exiting','terminated','archived')),criticality text not null default 'low' check(criticality in('low','medium','high','critical')),criticality_dimensions jsonb not null default '{}',criticality_methodology text not null default 'evidence_based_dimension_rules',business_owner_ref text,technical_owner_ref text,procurement_owner_ref text,risk_owner_ref text,primary_region text,onboarding_status text not null default 'not_started',classification text,status_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_vendors' and organization_id is not null)or(context_type='masterapp_platform_vendors' and organization_id is null)),unique(context_type,organization_id,third_party_ref));
create table public.vendor_lifecycle_events(id bigint generated always as identity primary key,vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,event_type text not null check(event_type in('identified','evaluated','approved','onboarded','activated','renewed','restricted','suspended','offboarding_started','terminated','archived')),from_status text,to_status text,reason text not null,approval_ref text,actor_id uuid references auth.users(id),created_at timestamptz not null default now());
create table public.vendor_onboarding_cases(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,onboarding_type text not null check(onboarding_type in('standard','critical','technology','supplier','logistics','payment','marketplace','custom')),status text not null default 'draft' check(status in('draft','collecting_information','under_review','blocked','approved','rejected','completed','cancelled')),owner_ref text not null,started_at timestamptz not null default now(),due_at timestamptz,completed_at timestamptz,policy_profile_ref text,approval_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vendor_onboarding_requirements(id uuid primary key default gen_random_uuid(),onboarding_case_id uuid not null references public.vendor_onboarding_cases(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,requirement_type text not null,required boolean not null,owner_ref text not null,evidence_ref text,review_status text not null default 'pending' check(review_status in('pending','provided','under_review','approved','rejected','waived','expired')),expires_at timestamptz,policy_ref text,approval_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(onboarding_case_id,requirement_type));
create table public.vendor_due_diligence_reviews(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,version integer not null check(version>0),dimension text not null check(dimension in('operational','financial','security','privacy_data','continuity','contractual','quality','technical','concentration','integration')),status text not null default 'not_started' check(status in('not_started','in_progress','satisfactory','satisfactory_with_conditions','unsatisfactory','inconclusive')),evidence_refs jsonb not null default '[]',coverage text not null default 'unknown',methodology text not null,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,valid_until timestamptz,created_at timestamptz not null default now(),unique(vendor_profile_id,version,dimension));
create table public.vendor_due_diligence_findings(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.vendor_due_diligence_reviews(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,dimension text not null,severity text not null check(severity in('info','low','medium','high','critical')),finding text not null,evidence_ref text,remediation_ref text,status text not null default 'open' check(status in('open','in_progress','resolved','accepted','dismissed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vendor_contract_links(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,contract_id uuid not null references public.contracts(id) on delete restrict,relationship_type text not null default 'primary',status text not null default 'active',created_at timestamptz not null default now(),unique(vendor_profile_id,contract_id));
create table public.vendor_performance_profiles(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,vendor_type text not null,period_type text not null check(period_type in('month','quarter','rolling_window','custom')),period_start date not null,period_end date not null,methodology jsonb not null default '{}',source_refs jsonb not null default '[]',status text not null default 'draft',created_at timestamptz not null default now(),check(period_end>=period_start));
create table public.vendor_performance_measurements(id uuid primary key default gen_random_uuid(),performance_profile_id uuid not null references public.vendor_performance_profiles(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,dimension text not null,value numeric,unit text,target numeric,state text not null default 'unknown' check(state in('meeting','at_risk','below_target','unknown','not_applicable')),evidence_ref text,source_metric_ref text,measured_at timestamptz not null default now());
create table public.vendor_sla_profiles(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,contract_id uuid references public.contracts(id) on delete restrict,service_ref text not null,metric_ref text not null,target numeric not null,comparison text not null default 'gte' check(comparison in('gte','lte')),measurement_window text not null,exclusions_ref text,effective_from date not null,effective_to date,version integer not null check(version>0),status text not null default 'draft' check(status in('draft','active','expired','retired')),created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),unique(vendor_profile_id,service_ref,metric_ref,version));
create table public.vendor_sla_events(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,sla_profile_id uuid not null references public.vendor_sla_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,period text not null,measured_value numeric,target numeric not null,status text not null check(status in('meeting','at_risk','breach_candidate','breached_reviewed','unknown')),evidence_ref text,review_status text not null default 'pending' check(review_status in('pending','confirmed','dismissed','inconclusive')),commercial_claim_candidate boolean not null default false,created_at timestamptz not null default now(),unique(sla_profile_id,period));
create table public.vendor_cost_snapshots(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,contract_ref text,service_ref text,period text not null,currency text not null,cost_type text not null check(cost_type in('purchase_spend','subscription','usage','fixed_fee','variable_fee','support','implementation','professional_services','unknown')),cost_state text not null check(cost_state in('committed','actual','estimated','allocated')),amount numeric not null,source_domain text not null,source_ref text not null,data_quality text not null default 'unknown',created_at timestamptz not null default now(),unique(vendor_profile_id,period,currency,cost_type,cost_state,source_domain,source_ref));
create table public.vendor_commercial_variances(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,period text not null,currency text not null,contracted numeric,invoiced numeric,usage_calculated numeric,actual numeric,variance numeric,status text not null default 'candidate' check(status in('candidate','under_review','confirmed','dismissed','resolved')),evidence_refs jsonb not null default '[]',created_at timestamptz not null default now());
create table public.vendor_risk_links(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,risk_profile_id uuid references public.third_party_risk_profiles(id) on delete restrict,risk_id uuid references public.enterprise_risks(id) on delete restrict,link_status text not null default 'confirmed' check(link_status in('candidate','confirmed','rejected','historical')),created_at timestamptz not null default now(),check(risk_profile_id is not null or risk_id is not null));
create table public.vendor_continuity_links(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,continuity_service_profile_id uuid references public.continuity_service_profiles(id) on delete restrict,continuity_plan_id uuid references public.continuity_plans(id) on delete restrict,fallback_ref text,last_test_ref text,readiness text not null default 'unknown',created_at timestamptz not null default now(),check(continuity_service_profile_id is not null or continuity_plan_id is not null));
create table public.vendor_dependency_links(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,entity_type text not null check(entity_type in('application','service','process','capability','store','region','data_asset','integration')),entity_ref text not null,relationship_ref text,evidence_status text not null default 'candidate' check(evidence_status in('candidate','confirmed','rejected')),critical boolean not null default false,created_at timestamptz not null default now(),unique(vendor_profile_id,entity_type,entity_ref));
create table public.vendor_alternatives(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,alternate_vendor_ref text not null,service_capability_ref text not null,qualification_status text not null check(qualification_status in('identified','evaluating','qualified','rejected','archived')),readiness text not null check(readiness in('identified','evaluating','qualified','partially_ready','ready','rejected','archived')),estimated_switch_days integer,validated_evidence_ref text,failover_test_ref text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vendor_renewal_cases(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,contract_id uuid references public.contracts(id) on delete restrict,renewal_date date,notice_deadline date,status text not null default 'upcoming' check(status in('upcoming','review_required','under_review','recommended_renew','recommended_renegotiate','recommended_exit','approved_renew','nonrenewal_planned','completed','cancelled')),owner_ref text not null,review_started_at timestamptz,decision_ref uuid,review_pack jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vendor_reviews(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,review_type text not null check(review_type in('onboarding','monthly_operational','quarterly_business','annual','renewal','post_incident','risk','exit')),review_pack jsonb not null default '{}',actions jsonb not null default '[]',decision_ref text,status text not null default 'draft',reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.vendor_decisions(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,decision_type text not null check(decision_type in('renew','renew_with_conditions','renegotiate','consolidate','replace','exit','suspend','continue_review')),rationale text not null,evidence_refs jsonb not null default '[]',approval_ref text not null,decision_maker_ref text not null,decided_at timestamptz not null default now(),safe_metadata jsonb not null default '{}');
alter table public.vendor_renewal_cases add constraint vendor_renewal_decision_fk foreign key(decision_ref) references public.vendor_decisions(id) on delete set null;
create table public.vendor_exit_plans(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,contract_ref text,scenario text not null check(scenario in('planned_nonrenewal','performance_exit','risk_exit','strategic_consolidation','provider_shutdown','emergency_exit','contract_end','custom')),owner_ref text not null,status text not null default 'draft' check(status in('draft','review','approved','in_progress','blocked','validating','completed','cancelled')),target_exit_date date,replacement_vendor_ref text,plan_version integer not null check(plan_version>0),architecture_analysis_ref text,change_request_ref text,approval_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(vendor_profile_id,plan_version));
create table public.vendor_exit_plan_steps(id uuid primary key default gen_random_uuid(),exit_plan_id uuid not null references public.vendor_exit_plans(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,step_type text not null check(step_type in('dependencies','replacement','data_export_migration','credentials_access','integration_cutover','contract_termination','financial_reconciliation','data_deletion_return_evidence','operational_validation','closure')),status text not null default 'pending' check(status in('pending','in_progress','blocked','completed','waived')),owner_ref text not null,evidence_ref text,requires_domain_action boolean not null default true,domain_action_ref text,sequence_no integer not null,created_at timestamptz not null default now(),unique(exit_plan_id,step_type));
create table public.vendor_offboarding_cases(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,exit_plan_id uuid references public.vendor_exit_plans(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,status text not null default 'planned' check(status in('planned','in_progress','blocked','validating','completed','cancelled')),policy_ref text,owner_ref text not null,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.vendor_access_references(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,access_type text not null check(access_type in('system','data','integration','credential','service_account','oauth','sso')),resource_ref text not null,credential_ref text,access_level text not null check(access_level in('none','metadata','operational','confidential','sensitive')),status text not null default 'active' check(status in('active','restricted','revocation_requested','revoked','unknown')),source_domain text not null,created_at timestamptz not null default now(),unique(vendor_profile_id,access_type,resource_ref));
create table public.vendor_governance_exceptions(id uuid primary key default gen_random_uuid(),vendor_profile_id uuid not null references public.vendor_profiles(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,exception_type text not null,reason text not null,scope jsonb not null,approval_ref text not null,approved_by uuid references auth.users(id),expires_at timestamptz not null,status text not null default 'active' check(status in('requested','active','expired','revoked','rejected')),policy_exception_ref text,created_at timestamptz not null default now());
create table public.vendor_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,job_type text not null check(job_type in('performance_refresh','sla_refresh','cost_aggregation','renewal_refresh','dependency_analysis','vendor360_refresh','health_check')),vendor_profile_id uuid references public.vendor_profiles(id) on delete cascade,status text not null default 'queued' check(status in('queued','running','completed','failed','dead_letter')),payload jsonb not null default '{}',attempt_count integer not null default 0,available_at timestamptz not null default now(),lease_expires_at timestamptz,error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.vendor_audit_events(id bigint generated always as identity primary key,context_type public.vendor_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),action text not null,resource_type text not null,resource_id text,correlation_id text,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());

create function public.prevent_vendor_history_rewrite() returns trigger language plpgsql set search_path=public as $$begin raise exception 'VENDOR_HISTORY_IMMUTABLE';end$$;
create trigger vendor_decisions_immutable before update or delete on public.vendor_decisions for each row execute function public.prevent_vendor_history_rewrite();
create trigger vendor_lifecycle_immutable before update or delete on public.vendor_lifecycle_events for each row execute function public.prevent_vendor_history_rewrite();
revoke all on function public.prevent_vendor_history_rewrite() from public,anon,authenticated;grant execute on function public.prevent_vendor_history_rewrite() to service_role;

create index vendor_profiles_scope_idx on public.vendor_profiles(context_type,organization_id,relationship_status,criticality);
create index vendor_profiles_supplier_idx on public.vendor_profiles(organization_id,supplier_id) where supplier_id is not null;
create index vendor_onboarding_board_idx on public.vendor_onboarding_cases(organization_id,status,due_at);
create index vendor_due_diligence_idx on public.vendor_due_diligence_reviews(organization_id,status,valid_until);
create index vendor_contract_links_idx on public.vendor_contract_links(organization_id,contract_id,status);
create index vendor_performance_period_idx on public.vendor_performance_profiles(organization_id,vendor_profile_id,period_end desc);
create index vendor_sla_status_idx on public.vendor_sla_events(organization_id,status,created_at desc);
create index vendor_cost_period_idx on public.vendor_cost_snapshots(organization_id,period,currency,vendor_profile_id);
create index vendor_renewal_deadline_idx on public.vendor_renewal_cases(organization_id,notice_deadline,renewal_date,status);
create index vendor_exit_status_idx on public.vendor_exit_plans(organization_id,status,target_exit_date);
create index vendor_jobs_queue_idx on public.vendor_jobs(status,available_at,lease_expires_at);
create index vendor_audit_lookup_idx on public.vendor_audit_events(context_type,organization_id,created_at desc);

create view public.vendor_portfolio_overview with(security_invoker=true) as select context_type,organization_id,count(*) filter(where relationship_status='active') active_vendors,count(*) filter(where criticality='critical' and relationship_status not in('terminated','archived')) critical_vendors,count(*) filter(where onboarding_status not in('not_started','completed','cancelled')) onboarding_in_progress,count(*) filter(where relationship_status='exiting') exiting_vendors from public.vendor_profiles group by context_type,organization_id;

do $$declare t text;begin foreach t in array array['vendor_member_permissions','vendor_profiles','vendor_lifecycle_events','vendor_onboarding_cases','vendor_onboarding_requirements','vendor_due_diligence_reviews','vendor_due_diligence_findings','vendor_contract_links','vendor_performance_profiles','vendor_performance_measurements','vendor_sla_profiles','vendor_sla_events','vendor_cost_snapshots','vendor_commercial_variances','vendor_risk_links','vendor_continuity_links','vendor_dependency_links','vendor_alternatives','vendor_renewal_cases','vendor_reviews','vendor_decisions','vendor_exit_plans','vendor_exit_plan_steps','vendor_offboarding_cases','vendor_access_references','vendor_governance_exceptions','vendor_jobs','vendor_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on public.vendor_portfolio_overview from public,anon,authenticated;grant select on public.vendor_portfolio_overview to service_role;

insert into public.feature_definitions(feature_key,name,description,category,value_type,default_value,safe_default,client_safe,owner_label,lifecycle_status,created_at,updated_at) values
('vendor_management_enabled','Vendor Management','Ativa perfis e governança do ciclo de terceiros.','governance','boolean','false','false',false,'Vendor Management','active',now(),now()),('vendor_due_diligence_enabled','Vendor Due Diligence','Ativa reviews dimensionais baseadas em evidência.','governance','boolean','false','false',false,'Vendor Management','active',now(),now()),('vendor_renewal_management_enabled','Vendor Renewals','Ativa calendário, cases e packs de renovação.','governance','boolean','false','false',false,'Vendor Management','active',now(),now()),('vendor_exit_planning_enabled','Vendor Exit Planning','Ativa planejamento controlado de saída e substituição.','governance','boolean','false','false',false,'Vendor Management','active',now(),now()),('vendor_sla_management_enabled','Vendor SLA Management','Ativa governança de SLA contratual sem duplicar SLO.','governance','boolean','false','false',false,'Vendor Management','active',now(),now()) on conflict(feature_key) do update set name=excluded.name,description=excluded.description,updated_at=now();

